/// Returns the index of a minimum element in the suffix `a[i..]`.
/// Precondition: `i < a.len()`.
///
/// If multiple minima exist, this returns the first one in the suffix.
pub fn look_for_min(a: &[i32], i: usize) -> usize {
    debug_assert!(i < a.len(), "start index must be within the array");

    let mut min_idx = i;
    for j in (i + 1)..a.len() {
        if a[j] < a[min_idx] {
            min_idx = j;
        }
    }
    min_idx
}

